<script lang="ts">
 import { onMount } from 'svelte'; import InlineError from '$lib/components/InlineError.svelte'; import { listAdminPackages, moderateAdminPackage } from '$lib/api/admin'; import { ApiError } from '$lib/api/types'; import type { AdminPackageSummary } from '$lib/api/types'; let packages:AdminPackageSummary[]=[]; let error=''; async function load(){try{packages=(await listAdminPackages()).packages;}catch(err){error=err instanceof ApiError?err.message:'Unable to load packages.';}} async function hide(id:string){if(!confirm('Set this package visibility to private?'))return; await moderateAdminPackage(id); await load();} onMount(load);
</script><section class="admin-page"><header class="admin-header"><div><h1>Packages</h1><p>Moderate package metadata without deleting archives.</p></div><nav class="admin-nav"><a href="/admin">Overview</a><a href="/admin/users">Users</a><a href="/admin/packages">Packages</a><a href="/admin/feedback">Feedback</a><a href="/admin/supporters">Supporters</a><a href="/admin/audit">Audit</a></nav></header><InlineError message={error}/><section class="panel"><table><thead><tr><th>Name</th><th>Visibility</th><th>Workspace</th><th>Owner</th><th></th></tr></thead><tbody>{#each packages as pkg}<tr><td>{pkg.name}<br/><small>{pkg.description}</small></td><td>{pkg.visibility}</td><td>{pkg.workspace_name}</td><td>{pkg.owner_email}</td><td>{#if pkg.visibility === 'public'}<button class="danger" onclick={() => hide(pkg.id)}>Set private</button>{/if}</td></tr>{/each}</tbody></table></section></section>
